    const label = link.textContent.trim().toLowerCase();
    if (path === 'home') link.href = '/';
    if (path === 'learn') link.href = '/learn';
    if (path === 'community') link.href = '/directory';
    if (path === 'directory') link.href = '/directory';
    if (path === 'login') link.href = '/membership#login';
    if (path === 'membership') link.href = label.includes('join') || label.includes('apply') || label.includes('listed') || label.includes('eligibility') || label.includes('free tier') || label.includes('neo member') || label.includes('membership plans') ? '/membership#registration' : '/membership';
    if (path === 'about') link.href = label.includes('privacy') ? '/legal#privacy' : label.includes('terms') ? '/legal#terms' : label.includes('partner ecosystem') ? '/about#partners' : '/about';
  });
  document.querySelectorAll('a[aria-label="Facebook"], a[aria-label="Instagram"], a[aria-label="TikTok"], a[aria-label="YouTube"]').forEach((link) => link.href = '/about#contact');
  document.querySelectorAll('a[aria-label="Share"]').forEach((link) => link.href = '/about#contact');
  document.querySelectorAll('a[aria-label="Email"]').forEach((link) => link.href = 'mailto:hello@flameph.org');
  document.querySelectorAll('a[aria-label="Website"]').forEach((link) => link.href = '/');
</script>
@include('partials.mobile-navigation')
</body></html>
